const mockExam1FinalFixes=[
  {id:'m1-36',stem:'[C]\nMom: You look so tired.\nKen: I slept late.\nMom: What time did you go to bed last night?\nKen: Ten to twelve. I prepared for my math, English and history tests.\nMom: You should study harder. You failed the math test last time.\nKen: OK. I will.\nMom: You are sleepy. I will make you a cup of coffee.\nKen: No, thank you. I will buy one on my way to school.\nMom: I can drive you to school.\nKen: No, thank you. I walk to school.\nMom: I see.\n\nKen went to bed at _____ last night.',options:['12:10','11:50','10:12','11:10'],answer:1,explanation:'Ten to twelve means 11:50.'},
  {id:'m1-37',stem:'[C]\nMom: You look so tired.\nKen: I slept late.\nMom: What time did you go to bed last night?\nKen: Ten to twelve. I prepared for my math, English and history tests.\nMom: You should study harder. You failed the math test last time.\nKen: OK. I will.\nMom: You are sleepy. I will make you a cup of coffee.\nKen: No, thank you. I will buy one on my way to school.\nMom: I can drive you to school.\nKen: No, thank you. I walk to school.\nMom: I see.\n\nHow does Ken go to school?',options:['He goes to school on foot.','He goes to school by bike.','His mother drives him to school.','He goes to school by taxi.'],answer:0,explanation:'Ken says, “I walk to school,” so he goes on foot.'},
  {id:'m1-38',stem:'[C]\nMom: You look so tired.\nKen: I slept late.\nMom: What time did you go to bed last night?\nKen: Ten to twelve. I prepared for my math, English and history tests.\nMom: You should study harder. You failed the math test last time.\nKen: OK. I will.\nMom: You are sleepy. I will make you a cup of coffee.\nKen: No, thank you. I will buy one on my way to school.\nMom: I can drive you to school.\nKen: No, thank you. I walk to school.\nMom: I see.\n\nWhich of the sentences is TRUE?',options:['Ken has a Chinese test today.','Ken will buy a cup of coffee after school.','Ken went to bed late last night.','Ken forgot to prepare for the test.'],answer:2,explanation:'Ken says he slept late, so he went to bed late.'},
  {id:'m1-39',table:'<table class="me-table"><tr><th colspan="2">Willy\'s</th></tr><tr><td>Open hours</td><td>11:00 a.m. ~ 9:00 p.m.<br>Sunday ~ Friday</td></tr><tr><td>Combo (套餐)</td><td>Hamburger + Fish Soup $120<br>Hamburger + Salad $110</td></tr><tr><td>Burgers</td><td>Chicken Burger $100<br>Hamburger $50<br>Cheeseburger $80</td></tr><tr><td>Soups</td><td>Fish Soup $80<br>Corn Soup $50</td></tr><tr><td>Drinks</td><td>Ice Tea $100<br>Coffee $120<br>Juice $80<br>Coke $50<br>Bottled water $30</td></tr></table>',stem:'Emma bought a hamburger, a fish soup and a cup of coffee for lunch. How much did she spend?',options:['Two hundred and fifty dollars.','Two hundred and forty dollars.','Two hundred dollars.','One hundred and seventy dollars.'],answer:1,explanation:'The hamburger and fish soup combo costs $120, plus coffee $120, for $240.'},
  {id:'m1-40',table:'<table class="me-table"><tr><th colspan="2">Willy\'s</th></tr><tr><td>Open hours</td><td>11:00 a.m. ~ 9:00 p.m.<br>Sunday ~ Friday</td></tr><tr><td>Combo (套餐)</td><td>Hamburger + Fish Soup $120<br>Hamburger + Salad $110</td></tr><tr><td>Burgers</td><td>Chicken Burger $100<br>Hamburger $50<br>Cheeseburger $80</td></tr><tr><td>Soups</td><td>Fish Soup $80<br>Corn Soup $50</td></tr><tr><td>Drinks</td><td>Ice Tea $100<br>Coffee $120<br>Juice $80<br>Coke $50<br>Bottled water $30</td></tr></table>',stem:'Which of the sentences is TRUE?',options:["Willy's is a bookstore.",'A cup of coffee is cheaper than bottled water.','It opens nine hours a day.','It is closed on Saturday.'],answer:3,explanation:'The menu says Sunday–Friday, so Willy’s is closed on Saturday.'}
];
mockExam1FinalFixes.forEach(f=>{const q=window.MockEnglishQuestionBank.find(x=>x.id===f.id);if(q)Object.assign(q,f)});
window.MockEnglishQuestionBank.sort((a,b)=>a.paper-b.paper||a.no-b.no);

function m13(no,section,stem,options,answer,explanation){return {id:`m13-${String(no).padStart(2,'0')}`,paper:13,no,section,stem,options,answer,explanation};}
window.MockEnglishQuestionBank.push(
 m13(1,'Vocabulary','On the _____ of the house, there is a flag.',['head','street','garden','top'],3,'旗子在屋頂上，用 top。'),m13(2,'Vocabulary','I _____ on the door many times, but no one answered it.',['knocked','collected','burned','lent'],0,'knock on the door 表示敲門。'),m13(3,'Vocabulary','All my family have gone to Japan, so I feel a little _____ at home by myself.',['lonely','perfect','possible','proud'],0,'獨自在家會感到 lonely。'),m13(4,'Vocabulary','Most leaves _____ their color in fall.',['change','cover','snow','rain'],0,'秋天葉子會 change color。'),m13(5,'Vocabulary','Which dessert did you _____ last time?',['afraid','order','hang','raise'],1,'點甜點用 order。'),m13(6,'Vocabulary',"Be _____ of yourself. I'm sure you'll do a good job.",['scared','afraid','crazy','confident'],3,'be confident of yourself 表示對自己有信心。'),m13(7,'Vocabulary','The coffee _____ is famous for its cakes.',['month','beauty','shop','hole'],2,'coffee shop 是咖啡店。'),m13(8,'Vocabulary','_____ is on December 24.',["New Year's Eve","New Year's Day",'Christmas Eve','Christmas Day'],2,'12 月 24 日是 Christmas Eve。'),m13(9,'Vocabulary','Mr. Wang keeps some _____ on his farm, and they can give milk.',['tails','cows','bees','ducks'],1,'會產奶的是 cows。'),m13(10,'Vocabulary',"Robots are really cool, but they can't make _____ for us.",['life','child','decisions','word'],2,'make decisions 表示做決定。'),
 m13(11,'Grammar','Joanna _____ English and _____ to English songs every evening.',['studys; listens','studies; listens','study; listen','studying; listening'],1,'Joanna 是單數；study 變 studies，listen 變 listens。'),m13(12,'Grammar','Listening to loud music too often has _____ David’s ears.',['hurts','hurting','to hurt','hurt'],3,'has + 過去分詞；hurt 的過去分詞也是 hurt。'),m13(13,'Grammar','Ann: Is Emily _____, please?\nRoy: Sorry. She is not _____.',['here; here','there; there','here; there','there; here'],3,'電話中問對方在不在用 there；回覆不在這裡用 here。'),m13(14,'Grammar','Tiffany goes to the department store _____ the taxi.',['by','in','take','on'],1,'搭乘特定交通工具可用 in the taxi。'),m13(15,'Grammar',"You didn't answer the phone this morning.\nSorry. I _____ when you called.",['am swimming','swim','was swimming','swimming'],2,'過去某時間正在進行，用 was swimming。'),m13(16,'Grammar','You can post any ideas _____ you want to share on the social network.',['that','whom','they','which'],0,'ideas 是物，關係代名詞用 that。'),m13(17,'Grammar','The cookies _____ on the dining table just now, but they _____ there now.',['were; weren’t','are; weren’t','were; are','were; aren’t'],3,'just now 用過去式；now 用現在式。'),m13(18,'Grammar','Animals are part of nature just like _____.',['us','we','our','ourselves'],0,'like 是介系詞，後接受格 us。'),m13(19,'Grammar','This is _____ first watch. I like _____ a lot.',['the; them','my; it','its; it','×; them'],1,'watch 單數，my first watch；代替單數物用 it。'),m13(20,'Grammar','Which is your favorite, _____?',['a cat or dogs','a cat or a dog','cats and dogs','cats or a dog'],1,'兩個單數選項的正確表達是 a cat or a dog。'),
 m13(21,'Cloze-test','Emma: My dad bought an e-book reader because _____ out to a bookstore is not convenient for me.',['go','goes','going','to go'],2,'動名詞 going 作主詞。'),m13(22,'Cloze-test','You can find _____ of books on the Internet.',['two thousands','thousands','hundred','the hundred'],1,'thousands of + 複數名詞。'),m13(23,'Cloze-test','You only care _____ that.',['on','with','at','about'],3,'care about 表示在意。'),m13(24,'Cloze-test','What would you do if a listener _____ was not polite called you during a live show?',['which','who','whom','×'],1,'listener 是人且作主詞，用 who。'),m13(25,'Cloze-test',"That's easy. I would _____ on them.",['grow up','wake up','show up','hang up'],3,'掛電話用 hang up on someone。'),m13(26,'Cloze-test',"We don't want to make our listeners _____.",['being angry','to be angry','angry','angrily'],2,'make + 受詞 + 形容詞。'),m13(27,'Cloze-test','Ken _____ her to a big night market last night.',['took','take','went','go'],0,'last night 用過去式 took。'),m13(28,'Cloze-test','Fanny was _____, so she started with watermelon juice.',['angry','sad','happy','thirsty'],3,'先喝果汁表示口渴。'),m13(29,'Cloze-test','_____ it smelled terrible, it was still her favorite snack.',['So','Both','Although','When'],2,'前後轉折用 Although。'),m13(30,'Cloze-test','She thought pig’s blood cake _____ wonderful!',['grew','looked','tasted','drank'],2,'食物吃起來很棒，用 tasted。'),
 m13(31,'Reading','[A] The reading gives five ideas to feel better when you are in a bad mood: exercise, rest, eat right, look at the bright side, and make someone smile.\n\nWhat is the best title?',['Five Things That Make People Feel Bad','Great Ways to Show Your Anger','Easy Ways to Make You Feel Better','Favorite Things for Happy People to Do'],2,'全文提供改善心情的方法。'),m13(32,'Reading','[A] One idea says: “Make someone else smile. Bring happiness to someone else.”\n\nWhat may change your mood when you feel sad?',['Eating all the food you want.','Giving someone a surprise gift.','Watching TV or movies all day.','Staying up late to play computer games.'],1,'讓別人開心可使自己感覺更好。'),m13(33,'Reading','[B] Mike practices basketball after school and plays tennis or badminton on weekends with Jason.\n\nWho might join a tennis game?',['Jack','Mike','Peter','Ken'],1,'Mike 在週末打網球或羽球。'),m13(34,'Reading','[B] Peter has a band with Jack, Ken, and Alan. Mike plays sports with Jason.\n\nWho is NOT in the school band?',['Ken','Peter','Jason','Alan'],2,'樂團成員有 Peter、Jack、Ken、Alan，沒有 Jason。'),m13(35,'Reading','[B] Mike plays tennis or badminton on weekends.\n\nWhat does Mike do on the weekend?',['He plays basketball.','He plays the bass.','He plays baseball.','He plays badminton.'],3,'文章直接提到 badminton。'),m13(36,'Reading','[B] Peter’s band will have a concert at school.\n\nWhat does “concert” mean?',['A robot show.','A basketball game.','A computer game.','A music show.'],3,'concert 是音樂表演。'),m13(37,'Reading','[B] Mike and Peter are twins. All the girls at school like Mike very much.\n\nWhich is NOT true?',['No girls at school like Mike.','Jack is a member of the school band.','Jason also likes sports.','Mike and Peter are the same age.'],0,'文章說所有女生都很喜歡 Mike，A 與文意相反。'),m13(38,'Reading','[C] Great World sells plants, roses, lilies and cards; it is holding a clearance sale.\n\nWhat is Great World?',['A bookstore.','A bank.','A flower shop.','A restaurant.'],2,'商品都是花卉相關，為花店。'),m13(39,'Reading','[C] Sale: five roses were $250 and are 10% off; two lilies are $210.\n\nVicky bought ten roses and two lilies. How much did she spend?',['$920','$870','$710','$660'],3,'十朵玫瑰為兩組：250×0.9×2=450；加百合 210，共 660。'),m13(40,'Reading','[C] Great World is open Sunday to Friday, 11 a.m. to 10 p.m.\n\nWhich is true?',['The sale lasts three weeks.','It opens six days a week.','It opens ten hours a day.','You can send an e-mail to Doris.'],1,'從星期日到星期五共六天。')
);
window.MockEnglishQuestionBank.sort((a,b)=>a.paper-b.paper||a.no-b.no);

function m12(no, section, stem, options, answer, explanation) { return {id:`m12-${String(no).padStart(2,'0')}`,paper:12,no,section,stem,options,answer,explanation}; }
window.MockEnglishQuestionBank.push(
 m12(1,'Vocabulary','Emma: What did you do yesterday?\nTony: I _____ my uncle.',['typed','decided','visited','celebrated'],2,'visit a person 表示拜訪某人。'),
 m12(2,'Vocabulary',"It is common to give a red _____ on Chinese New Year's Eve.",['envelope','bedroom','paper','garage'],0,'red envelope 是紅包。'),
 m12(3,'Vocabulary','The dining room was _____ with posters.',['decorated','touched','invited','watched'],0,'be decorated with 表示用…裝飾。'),
 m12(4,'Vocabulary','Did you _____ that Tommy had left the room?',['play','notice','review','repeat'],1,'notice that 表示注意到。'),
 m12(5,'Vocabulary','Ben won the speech contest. His parents are _____ of him.',['sorry','afraid','proud','embarrassed'],2,'be proud of 表示以…為榮。'),
 m12(6,'Vocabulary','This plane can carry at least 200 _____.',['passengers','mountains','sports','programs'],0,'飛機載運的是 passengers（乘客）。'),
 m12(7,'Vocabulary',"Neil: Are you _____? I don't believe it.\nSally: No, just kidding.",['popular','friendly','funny','serious'],3,'just kidding 表示開玩笑，問句是 Are you serious?'),
 m12(8,'Vocabulary','We plan to go _____ climbing this weekend. Are you coming?',['lake','river','mountain','earth'],2,'go mountain climbing 表示去爬山。'),
 m12(9,'Vocabulary','Benny is a _____ businessman. He makes a lot of money every year.',['dangerous','strange','successful','weak'],2,'能賺很多錢的生意人是 successful。'),
 m12(10,'Vocabulary','Meg ate too many desserts, so she had an upset _____.',['weight','stomach','finger','hair'],1,'have an upset stomach 表示胃不舒服。'),
 m12(11,'Grammar','Rita: _____ grape juice did he drink?\nAllen: He drank three glasses.',['How many','How often','How far','How much'],3,'juice 不可數，問數量用 How much。'),
 m12(12,'Grammar',"Lisa's room is larger than _____.",['me','my','I','mine'],3,'than 後面需用名詞所有格 mine，代表 my room。'),
 m12(13,'Grammar','Gary sometimes watches TV after _____ his homework.',['finishing','to finish','finishes','finish'],0,'after 後接 V-ing。'),
 m12(14,'Grammar','There are _____ students on the playground.',['a little','much','many','little'],2,'students 是可數複數名詞，用 many。'),
 m12(15,'Grammar',"Playing the violin _____ one of Willy's hobbies.",['are','will','be','is'],3,'動名詞片語作主詞，動詞用單數 is。'),
 m12(16,'Grammar',"Sally never drinks a cup of coffee, _____?",["doesn't she",'does she','will she',"isn't she"],1,'never 帶否定，附加問句用肯定 does she。'),
 m12(17,'Grammar','Rita: Where is your roommate?\nTed: She _____ to the USA. She will come back next week.',['has been','has gone','went','goes'],1,'人還在目的地、尚未回來，用 has gone to。'),
 m12(18,'Grammar','If Willy _____ the truth, his parents might not have argued.',['tells','will tell','had told','has told'],2,'與過去事實相反：If + had p.p., might have p.p.。'),
 m12(19,'Grammar','_____ are many notebooks on the desk. You can take one.',['There','They','He','We'],0,'There are 表示「有」。'),
 m12(20,'Grammar','Tina forgot _____ the mail in the post office. In fact, she sent it already.',['send','sending','to send','sent'],1,'forget + V-ing 表示忘記已經做過的事。'),
 m12(21,'Cloze-test',"Lisa: Good morning. How may I help you?\nDon: I'm calling from room no. 520. I'd like to order _____ in my room.",['toys','newspaper','numbers','breakfast'],3,'客房服務點餐是 order breakfast。'),
 m12(22,'Cloze-test','Don: Send a hamburger and _____ coffee, please.',['a loaf of','a cup of','a piece of','a dish of'],1,'咖啡的量詞用 a cup of。'),
 m12(23,'Cloze-test','Don: _____ would that be?',['How long','How much','How far','How often'],0,'詢問送達需要多久，用 How long。'),
 m12(24,'Cloze-test','Lisa: Your meal will _____ in thirty minutes.',['delivers','delivering','be delivered','delivered'],2,'meal 是被送達，用未來被動式 will be delivered。'),
 m12(25,'Cloze-test','Kelly likes to play the piano and go jogging when she has _____ time.',['bright','busy','funny','free'],3,'free time 是空閒時間。'),
 m12(26,'Cloze-test','She is _____ playing the piano because she has played it for many years.',['good at','surprised at','afraid of','tired of'],0,'be good at + V-ing 表示擅長。'),
 m12(27,'Cloze-test','Kelly’s younger brother Alan likes to play the piano, _____.',['either','neither','too','nor'],2,'肯定句句尾的「也」用 too。'),
 m12(28,'Cloze-test','Beth did not go to bed until 2 a.m. because she was worried _____ her job.',['at','about','for','with'],1,'be worried about 表示擔心。'),
 m12(29,'Cloze-test',"Beth felt so embarrassed _____ she couldn't say any word.",['that','to','for','which'],0,'so + 形容詞 + that 子句。'),
 m12(30,'Cloze-test','After lunch, she tried _____ to her boss, but he left the office already.',['explaining','explain','explained','to explain'],3,'try to V 表示嘗試做某事。'),
 m12(31,'Reading','[A] Molly tries on a sweater in a store. It fits her well. She decides to take it and pays by credit card.\n\nWhere is Molly probably?',['In a bookstore.','In a shopping center.','In a bank.','In a post office.'],1,'試穿毛衣的地方是購物中心／服飾店。'),
 m12(32,'Reading','[A] Molly asks, “Can I try on this sweater?”\n\nWhat does Molly try on?',['A skirt.','A shirt.','A coat.','A sweater.'],3,'對話直接說 sweater。'),
 m12(33,'Reading','[A] The clerk tells Molly, “Try a size 8.” Molly says it fits her well.\n\nWhat size does Molly wear?',['Size 6.','Size 8.','Size 10.','Size 12.'],1,'她試穿的八號合身。'),
 m12(34,'Reading','[A] Molly decides to buy a sweater for $3,000 and gives the clerk her credit card.\n\nWhich sentence is TRUE?',['The sweater is too small.',"Molly doesn't buy the sweater.",'Molly will pay with a credit card.','The sweater is less than $3,000.'],2,'她決定購買，並以信用卡付款。'),
 m12(35,'Reading','[B] Job form\nHelen: clerk, $25,000, 8 hours, communicate\nKelly: writer, $32,000, 6 hours, writing stories\nJenny: salesperson, $50,000, 10 hours, sell goods\nSonia: cook, $48,000, 9 hours, cook and train\n\nWho made the most money?',['Helen','Kelly','Jenny','Sonia'],2,'Jenny 的薪資 $50,000 最高。'),
 m12(36,'Reading','[B] Helen works eight hours a day. What does she do?',['She is a clerk.','She is a writer.','She is a salesperson.','She is a cook.'],0,'表格中 Helen 的職業是 clerk。'),
 m12(37,'Reading','[B] Which sentence is TRUE?',['Kelly works 8 hours a day.','Jenny is a writer.','Helen makes more money than Jenny does.','Sonia is good at cooking.'],3,'Sonia 的技能欄是 cook and train，符合擅長烹飪。'),
 m12(38,'Reading','[C] Mr. Pitt receives a note written by Rose, his secretary. Frank Cage left a contact number and is interested in the company product.\n\nWhat does Rose do?',['A clerk.','A driver.','A waitress.','A secretary.'],3,'題幹直接說 Rose 是 Mr. Pitt 的秘書。'),
 m12(39,'Reading','[C] Mr. Pitt got the note from his secretary after the meeting.\n\nWhy did Mr. Pitt miss this call?',['He was in the meeting.','He was out for lunch.','He was sick.',"He didn't want to talk to Mr. Cage."],0,'題幹說明便條是在會議後取得。'),
 m12(40,'Reading','[C] Frank Cage is interested in the products and asks about order amount and price. His contact number is on the note.\n\nWhich sentence is TRUE?',['Frank wrote this note.','Rose is interested in the products.','Frank may give out an order.','Frank did not leave his cellphone number.'],2,'Frank 對產品有興趣並詢問訂購資訊，可能下單。')
);
window.MockEnglishQuestionBank.sort((a,b)=>a.paper-b.paper||a.no-b.no);

function m11(no, section, stem, options, answer, explanation) {
  return {id:`m11-${String(no).padStart(2,'0')}`,paper:11,no,section,stem,options,answer,explanation};
}
window.MockEnglishQuestionBank.push(
  m11(1,'Vocabulary',"Gary: Where are you going?\nLisa: I'm going to the train _____.",['bookstore','bank','station','balcony'],2,'train station 是火車站。'),
  m11(2,'Vocabulary',"He doesn't know how to wash the clothes in _____.",['a washing machine','a refrigerator','a radio','an oven'],0,'洗衣服要使用 washing machine。'),
  m11(3,'Vocabulary','Remember to _____ these books to the library today.',['grow','laugh','return','hurt'],2,'把書還給圖書館用 return。'),
  m11(4,'Vocabulary','The man _____ finished his work before the deadline. He was so happy.',['around','quite','never','finally'],3,'finally 表示終於完成。'),
  m11(5,'Vocabulary',"Sandra's right hand _____. She can't ride a motorcycle.",['decides','hurts','flew','throws'],1,'手受傷應用 hurts。'),
  m11(6,'Vocabulary','Sandy: Where is Thomas?\nSteve: He is playing on the _____.',['envelope','stomach','playground','sky'],2,'在遊樂場玩是 play on the playground。'),
  m11(7,'Vocabulary','The air in the mountains is very _____, so he often goes mountain climbing.',['strange','convenient','fresh','low'],2,'山上的空氣很清新，用 fresh。'),
  m11(8,'Vocabulary','Please turn off the _____ before going to bed.',['plane','lamp','door','letter'],1,'睡前關燈是 turn off the lamp。'),
  m11(9,'Vocabulary','Judy lives in a very _____ apartment, so she enjoys staying at home.',['young','serious','handsome','comfortable'],3,'令人喜歡待在家的公寓是 comfortable。'),
  m11(10,'Vocabulary','The _____ checked Meg in, but he forgot to give her a key.',['clerk','cook','singer','customer'],0,'旅館為客人辦理入住的是 clerk。'),
  m11(11,'Grammar','The manager _____ a meeting every day. He is really busy.',['has','has had','is having','had'],0,'every day 表示習慣動作，用現在簡單式 has。'),
  m11(12,'Grammar',"The pretty girl _____ at the train station is Frank's new neighbor.",['that we saw her','we saw her','who saw','we saw'],3,'關係子句省略受格關係代名詞：the girl (that) we saw。'),
  m11(13,'Grammar',"Jill: _____ is the weather like in New York in winter?\nFred: It's snowy.",['How','Why','What','Where'],2,'詢問天氣的固定句型是 What is the weather like?'),
  m11(14,'Grammar','_____ of the dresses on the bed is made in Italy.',['Most','A lot','One','Many'],2,'one of + 複數名詞，動詞用單數 is。'),
  m11(15,'Grammar','Sonia works hard every day, and _____.',['so does Emma','Emma does so','neither does Emma','so is Emma'],0,'肯定附和：so + 助動詞 + 主詞。'),
  m11(16,'Grammar',"Brad didn't tell the truth. _____, he told a lie.",['In fact','But also','However','As a result'],0,'後句說明前句的事實，用 In fact。'),
  m11(17,'Grammar','_____ in the park is one of Mr. Jordan’s hobbies.',['Ran','Running','Run','Has ran'],1,'動名詞 Running 作主詞。'),
  m11(18,'Grammar','There are two bookstores in the department store. The one on the second floor sells magazines, but _____ doesn’t.',['the others','another','other','the other'],3,'兩者中的另一個用 the other。'),
  m11(19,'Grammar',"Molly didn't answer the phone _____ she fell asleep.",['although','since','before','if'],1,'因為睡著而沒接電話，用 since 表原因。'),
  m11(20,'Grammar','Mark: Yes. She is _____ girl I have ever seen in the world.',['more beautiful','beautiful','the most beautiful','most beautiful'],2,'範圍比較用最高級 the most beautiful。'),
  m11(21,'Cloze-test','Dad: You came home late today.\nSally: My car _____ down, and I took it to the shop.',['broke','skipped','sat','looked'],0,'break down 表示車子故障。'),
  m11(22,'Cloze-test','Dad: Oh, I see. _____ do you go to work tomorrow?\nSally: By bus.',['Why','How','Where','When'],1,'回答 By bus，問交通方式用 How。'),
  m11(23,'Cloze-test','Sally: In fact, I have never _____ the bus.',['take','took','taking','taken'],3,'have never + 過去分詞，take 的過去分詞是 taken。'),
  m11(24,'Cloze-test','Dad: _____ You can drive my car to work.',['Of course.','Sounds great.','Don’t worry.','Hurry up.'],2,'安慰對方並提出辦法，用 Don’t worry。'),
  m11(25,'Cloze-test','Frank is 16 years old. He just _____ from junior high school this year.',['remembered','erased','graduated','listened'],2,'從國中畢業用 graduated from。'),
  m11(26,'Cloze-test','He was starting senior high school. It was his _____ day of school.',['first','last','delicious','pink'],0,'剛開始高中，是第一天。'),
  m11(27,'Cloze-test','Frank was shy and quiet, so he felt worried. He _____ everything would be fine.',['missed','caught','pointed','hoped'],3,'hope + 子句表示希望。'),
  m11(28,'Cloze-test',"Ken and Lisa had a big dinner _____ Valentine's Day.",['in','on','at','with'],1,'特定節日前用 on。'),
  m11(29,'Cloze-test','He found his front door _____.',['recorded','jumped','touched','broken'],3,'門被破壞，應為 broken。'),
  m11(30,'Cloze-test','His TV and notebook were missing. Then Ken called the _____.',['police','waiter','clerk','writer'],0,'遭竊後應該報警。'),
  m11(31,'Reading','[A] Emma: Steve didn’t show up in the meeting. The manager looked angry.\nAdam: He had a car accident this morning and was sent to the hospital.\n\nSteve didn’t show up in the meeting because _____.',['he asked for a sick leave','he had a car accident','he got up late','he forgot the meeting'],1,'對話指出 Steve 早上出了車禍。'),
  m11(32,'Reading','[A] Steve didn’t show up in the meeting. The manager looked angry.\n\nWhy did the manager look angry this morning?',['He was late for work.','The meeting was too boring.','Emma didn’t pick up his phone.','Steve didn’t show up in the meeting.'],3,'經理生氣是因為 Steve 沒出席會議。'),
  m11(33,'Reading','[A] Steve had a car accident and was sent to the hospital.\n\nWhich sentence is TRUE?',['Emma is the manager.','Steve showed up in the meeting this morning.','Steve was in the hospital.','The manager had a car accident.'],2,'Steve 車禍後被送到醫院。'),
  m11(34,'Reading','[B] Class A has 20 boys and 15 girls.\nBoys: Milk 40%, Juice 30%, Coke 25%, Coffee 5%.\nGirls: Milk 40%, Coffee 26.7%, Coke 20%, Juice 13.3%.\n\nHow many students like to drink milk?',['Eight.','Fourteen.','Sixteen.','Eighty.'],1,'男生 20×40%=8，女生 15×40%=6，共 14 人。'),
  m11(35,'Reading','[B] Class A has 20 boys and 15 girls.\nBoys: Milk 40%, Juice 30%, Coke 25%, Coffee 5%.\nGirls: Milk 40%, Coffee 26.7%, Coke 20%, Juice 13.3%.\n\n_____ is the most popular drink in Class A.',['Juice','Coffee','Milk','Coke'],2,'牛奶共有 14 人，最多。'),
  m11(36,'Reading','[B] Class A has 20 boys and 15 girls. Boys: Coffee 5%; Girls: Coffee 26.7%.\n\nWhich sentence is TRUE?',['No one in Class A likes juice.','One boy student likes coffee.','Juice is more popular than Coke.','There are forty students in Class A.'],1,'20 位男生的 5% 是 1 位。'),
  m11(37,'Reading','[C] William writes to Rose: “If you have time, we can get to Lucky One this Saturday afternoon. How about meeting at five? Let’s talk over dinner.”\n\nWhat is Lucky One?',['A restaurant.','A post office.','A bank.','A bookstore.'],0,'約在 Lucky One 吃晚餐，所以是餐廳。'),
  m11(38,'Reading','[C] William wrote the letter on October 1, 2018. He says it has been two weeks since Rose came to his birthday party.\n\nWhen is William’s birthday?',['In August.','In September.','In October.','In November.'],1,'10 月 1 日往前兩週約在 9 月。'),
  m11(39,'Reading','[C] Rose left William’s birthday party angrily because they argued over a little thing.\n\nWhy did Rose leave the party angrily?',['She was not satisfied with the party.','She lost her purse.','She argued with William.','William didn’t talk to her.'],2,'信中直接說兩人為小事爭論。'),
  m11(40,'Reading','[C] William says he tried to call Rose, but she did not pick up.\n\nWhich sentence is TRUE?',['Rose wrote this letter.','William did not call Rose.','Rose felt sorry for William.','William tried to contact Rose.'],3,'William 曾嘗試打電話給 Rose。')
);
window.MockEnglishQuestionBank.sort((a,b)=>a.paper-b.paper||a.no-b.no);

function m10(no, section, stem, options, answer, explanation) {
  return {id:`m10-${String(no).padStart(2,'0')}`,paper:10,no,section,stem,options,answer,explanation};
}
window.MockEnglishQuestionBank.push(
  m10(1,'Vocabulary','Sandy: Did you watch the basketball game last night?\nSam: Yes. It was very _____. I really loved it.',['colorful','sleepy','delicious','exciting'],3,'籃球賽讓人喜愛，最適合用 exciting（刺激的）。'),
  m10(2,'Vocabulary','What time will the Christmas _____ start?',['party','game','story','gift'],0,'Christmas party 是「聖誕派對」。'),
  m10(3,'Vocabulary','The old man was walking _____ through the snow.',['slowly','truly','lovely','luckily'],0,'在雪地中走路，slowly（慢慢地）符合語意。'),
  m10(4,'Vocabulary','Gary will _____ at the airport at six o’clock.',['make','arrive','dance','remember'],1,'arrive at + 地點，表示抵達。'),
  m10(5,'Vocabulary','I felt _____ about falling down in front of my classmates.',['lucky','honest','pretty','embarrassed'],3,'在同學面前跌倒會感到 embarrassed（尷尬的）。'),
  m10(6,'Vocabulary','A stranger _____ the little girl to the store.',['jumped','followed','printed','forgot'],1,'follow + 人 + to + 地點，表示跟著某人到某地。'),
  m10(7,'Vocabulary','Helen is the prettiest girl in our class. No one _____ looks as pretty as she does.',['else','both','other','another'],0,'no one else 表示「沒有其他人」。'),
  m10(8,'Vocabulary','The coach planned to _____ two pounds a week.',['spend','lose','understand','turn'],1,'lose two pounds 表示減掉兩磅。'),
  m10(9,'Vocabulary','The man was so _____ that he saved the little girl.',['honest','brave','favorite','afraid'],1,'救人需要勇敢，brave 最符合句意。'),
  m10(10,'Vocabulary','Tina lives on the tenth _____. She takes the elevator every day.',['weight','step','homework','floor'],3,'第十樓是 the tenth floor。'),
  m10(11,'Grammar','Molly seldom washes the dishes, and Judy _____.',['does too','does so','neither does','doesn’t either'],3,'seldom 帶否定語意，附和否定用 doesn’t either。'),
  m10(12,'Grammar','I was born _____ January 20, 1999.',['in','at','on','of'],2,'特定日期前用 on。'),
  m10(13,'Grammar','If I were you, I _____ on a test.',['cheated','won’t cheat','wouldn’t cheat','may not cheat'],2,'與現在事實相反的假設：If I were you, I would not + 原形動詞。'),
  m10(14,'Grammar','_____ Meg _____ Mina is a student. They are both clerks.',['Neither; nor','Either; or','Both; and','Neither; or'],0,'兩人都不是學生，應用 Neither A nor B。'),
  m10(15,'Grammar','Don’t go out alone at midnight, _____?',['does it','will you','would you','do you'],1,'否定祈使句的附加問句通常用 will you?'),
  m10(16,'Grammar','It took two hours _____ her painting.',['finishing','to finish','finish','finished'],1,'It takes + 時間 + to V，表示花多少時間做某事。'),
  m10(17,'Grammar','Christmas is coming. Willy _____ decorate the house next week.',['is going','goes to','is going to','going to'],2,'be going to + 原形動詞表示計畫或未來。'),
  m10(18,'Grammar','Bill and Neil are neighbors. _____ of them are from the USA.',['One','Some','All','Both'],3,'兩人都來自美國，用 Both。'),
  m10(19,'Grammar','The man is rich enough _____ the island.',['to buy','buying','bought','bought'],0,'形容詞 + enough + to V。'),
  m10(20,'Grammar','This is the best book _____ I have ever read.',['that','which','who','where'],0,'先行詞有最高級 best 時，關係代名詞常用 that。'),
  m10(21,'Cloze-test','Emma: Mr. Cage, can I talk to you?\nMr. Cage: Sure. Have a _____, please.',['pen','seat','dream','video'],1,'Have a seat, please. 表示「請坐」。'),
  m10(22,'Cloze-test','Mr. Cage: We need to discuss your job performance last _____.',['next','each','every','week'],3,'談論過去的工作表現，last week 合乎語意。'),
  m10(23,'Cloze-test','Mr. Cage: You were _____ for work two times.',['careful','brave','late','glad'],2,'be late for work 表示上班遲到。'),
  m10(24,'Cloze-test','Mr. Cage: You also made some _____.',['mistakes','wishes','fun','doctors'],0,'make mistakes 是固定搭配。'),
  m10(25,'Cloze-test','Meg has two roommates, Sonia and Alisa. _____ Sonia is friendly and outgoing, she is very popular.',['Although','Since','If','Before'],1,'句子說明 Sonia 受歡迎的原因，Since 表示「因為」。'),
  m10(26,'Cloze-test','Unlike Sonia, Alisa is quiet and _____.',['noisy','happy','exciting','shy'],3,'和 outgoing 相反且符合安靜的特質是 shy。'),
  m10(27,'Cloze-test','Alisa does not know how to talk to people, so she has _____ friends.',['many','lots of','a few','much'],2,'friends 是可數名詞；語意是朋友不多，用 a few。'),
  m10(28,'Cloze-test','Emily’s birthday was coming, so Wendy _____ her a green bag.',['bought','cost','imagined','protected'],0,'buy someone something 表示買某物送給某人。'),
  m10(29,'Cloze-test','The bag _____ her two thousand dollars.',['cost','paid','spent','took'],0,'物品作主詞表示價格時用 cost。'),
  m10(30,'Cloze-test','Besides, she spent five thousand dollars _____ two pairs of shoes.',['at','with','within','on'],3,'spend money on + 事物。'),
  m10(31,'Reading','[A] Neil just moved into a new house, but he is unhappy. His neighbors are unfriendly. When he listens to music, Mrs. Wang knocks on his door and says, “Turn down the volume, or I’ll call the police.”\n\nWhy is Neil unhappy?',['He failed a test.','His neighbors are unfriendly.','He is afraid of moving.','He has no money.'],1,'文章直接說 Neil 的鄰居不友善。'),
  m10(32,'Reading','[A] Neil just moved into a new house. Mrs. Wang knocks on his door when he listens to music.\n\nWhy does Mrs. Wang knock on Neil’s door?',['To say hello.','To use his phone.','To call the police.','To ask him to turn down the volume.'],3,'Mrs. Wang 要他把音量轉小。'),
  m10(33,'Reading','[A] Neil just moved into a new house, but his neighbors are unfriendly.\n\nWhich is true about Neil?',['He knocked on Mrs. Wang’s door.','He just moved into a new apartment.','His neighbors are not friendly.','He gets along well with his neighbors.'],2,'文章明確說他的鄰居不友善。'),
  m10(34,'Reading','[B] Mark’s Home\nMon.–Sat.: 11:00–20:00\nSun.: 10:00–20:00\nAll you can eat and drink. Over 100 items.\n$500 / adult; $350 / child\nClosed on the first Sunday of every month.\n\nWhat is Mark’s Home?',['A museum.','A supermarket.','A swimming pool.','A restaurant.'],3,'提供吃到飽與飲料的場所是餐廳。'),
  m10(35,'Reading','[B] Mark’s Home is open from 11:00 to 20:00 on Friday.\n\nHow many hours is it open on Friday?',['Nine.','Eight.','Seven.','Ten.'],0,'從 11:00 到 20:00，共九小時。'),
  m10(36,'Reading','[B] Mark’s Home is closed on the first Sunday of every month.\n\nWhich is true?',['It opens every day of the year.','It is closed on the first Sunday of each month.','Children pay $500.','It opens at 9:00 on Sunday.'],1,'公告明確寫著每月第一個星期日休息。'),
  m10(37,'Reading','[C] Cindy’s diary\nMay 12, sunny: I went swimming with Lisa. Then we went shopping. I bought a skirt and a bag for $3,000.\nMay 14, Saturday, rainy: Our picnic was canceled, so I stayed home.\nMay 15: It was my birthday. We had dinner at a restaurant.\nMay 17, cloudy: I forgot my homework.\n\nWhat was the weather like on Saturday?',['Sunny.','Cloudy.','Windy.','Rainy.'],3,'日記寫 May 14（星期六）是 rainy。'),
  m10(38,'Reading','[C] May 14 was Saturday. What day was May 17?',['Monday.','Tuesday.','Wednesday.','Thursday.'],1,'5 月 14 日是星期六，5 月 17 日是星期二。'),
  m10(39,'Reading','[C] Cindy wrote: “I went swimming with Lisa on May 12.”\n\nWhat did Lisa do on May 12?',['She went swimming.','She went on a picnic.','She went camping.','She went jogging.'],0,'日記說 Cindy 與 Lisa 一起游泳。'),
  m10(40,'Reading','[C] Cindy’s diary records swimming on May 12, staying home on rainy Saturday, and her birthday on May 15.\n\nWhich is NOT true?',['Cindy stayed home on Saturday.','Cindy can swim.','Cindy bought a coat on May 12.','Her birthday was on May 15.'],2,'May 12 買的是裙子和包包，不是外套。')
);
window.MockEnglishQuestionBank.sort((a,b)=>a.paper-b.paper||a.no-b.no);
